class HighResource {
    int* ptr_;
public:
    // Move Constructor: Steal the resource
    HighResource(HighResource&& other) noexcept
        : ptr_(other.ptr_)
    {
        other.ptr_ = nullptr; // Nullify source
    }

    // Rule of Five (often implemented for safety)
    HighResource(const HighResource&) = delete;
    ~HighResource() { delete[] ptr_; }
};

class DataContainer {
    int* data;
public:
    // Move Assignment Operator
    DataContainer& operator=(DataContainer&& other) noexcept {
        if (this != &other) {
            delete[] data;          // 1. Release own resource
            data = other.data;      // 2. Steal
            other.data = nullptr;   // 3. Nullify source
        }
        return *this;
    }
};

void sink(std::string&& rval) {}

void demo_move() {
    std::string s1 = "source_data"; // Lvalue

    // Explicit Move (Casts Lvalue to Rvalue reference)
    std::string s2 = std::move(s1); 

    // s1 is now valid but empty/unspecified state

    // Using Rvalue directly
    sink("temporary"); 

    // Must use std::move for Lvalues to call rvalue function
    sink(std::move(s2)); 
}
